<?php defined('AUTOSAV_ROOT') or die; $e = static fn($v) => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); $isEdit = !empty($document); $action = $isEdit ? '/legal-documents/'.(int)$document['dju_id'].'/update' : '/legal-documents/store'; ?>
<div class="container-fluid py-3"><h1 class="h3"><?= $isEdit ? 'Modifier' : 'Créer' ?> un document juridique</h1><div class="card"><div class="card-body"><form method="post" action="<?= $e($action) ?>"><input type="hidden" name="_csrf_token" value="<?= $e($csrf_token ?? '') ?>"><div class="row"><div class="col-md-3"><label>Type</label><input class="form-control" name="dju_type_document" value="<?= $e($document['dju_type_document'] ?? 'cgu') ?>" required></div><div class="col-md-6"><label>Titre</label><input class="form-control" name="dju_titre" value="<?= $e($document['dju_titre'] ?? '') ?>" required></div><div class="col-md-3"><label>Version</label><input class="form-control" name="dju_version" value="<?= $e($document['dju_version'] ?? '1.0') ?>" required></div></div><div class="row mt-2"><div class="col-md-3"><label>Société propriétaire</label><select class="form-control" name="dju_societe_id"><option value="0">Global</option><?php foreach (($societes ?? []) as $s): ?><option value="<?= (int)$s['soc_id'] ?>" <?= ((int)($document['dju_societe_id'] ?? 0)===(int)$s['soc_id'])?'selected':'' ?>><?= $e($s['soc_nom']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label>Marque société</label><select class="form-control" name="dju_marque_societe_id"><option value="0">Aucune</option><?php foreach (($societes ?? []) as $s): ?><option value="<?= (int)$s['soc_id'] ?>" <?= ((int)($document['dju_marque_societe_id'] ?? 0)===(int)$s['soc_id'])?'selected':'' ?>><?= $e($s['soc_nom']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label>Valide du</label><input class="form-control" type="date" name="dju_valide_du" value="<?= $e($document['dju_valide_du'] ?? '') ?>"></div><div class="col-md-2"><label>Valide au</label><input class="form-control" type="date" name="dju_valide_au" value="<?= $e($document['dju_valide_au'] ?? '') ?>"></div><div class="col-md-2"><label>Statut</label><select class="form-control" name="dju_statut_id"><option value="0